import { cookies, headers } from 'next/headers';

function getPreferredLanguage(acceptLanguage: string | null): string {
  if (!acceptLanguage) return 'unknown';
  // Accept-Language format: "en-US,en;q=0.9,es;q=0.8" - first is preferred
  const first = acceptLanguage.split(',')[0]?.trim();
  return first || 'unknown';
}

export default async function ThemePreferences() {
  const cookieStore = await cookies();
  const headersList = await headers();

  const theme = cookieStore.get('theme')?.value ?? 'light';
  const acceptLanguage = headersList.get('accept-language');
  const preferredLanguage = getPreferredLanguage(acceptLanguage);

  return (
    <section className="rounded-lg border border-gray-200 bg-white p-6 shadow-sm dark:border-gray-700 dark:bg-gray-800">
      <h2 className="mb-4 text-lg font-semibold text-gray-900 dark:text-gray-100">
        Your Preferences
      </h2>
      <dl className="space-y-3">
        <div>
          <dt className="text-sm font-medium text-gray-500 dark:text-gray-400">
            Theme
          </dt>
          <dd className="mt-1 text-gray-900 dark:text-gray-100">{theme}</dd>
        </div>
        <div>
          <dt className="text-sm font-medium text-gray-500 dark:text-gray-400">
            Preferred Language
          </dt>
          <dd className="mt-1 text-gray-900 dark:text-gray-100">
            {preferredLanguage}
          </dd>
        </div>
      </dl>
    </section>
  );
}

